		local b = new("TextButton", { Position = UDim2.new(x, 0, 1, -66), Size = UDim2.new(0.42, 0, 0, 46), BackgroundColor3 = color, Text = text, Font = Enum.Font.Bangers, TextScaled = true, TextColor3 = Color3.new(1, 1, 1) }, body)
